// Las funciones de los scripts 148–167 lanzan 'LAB_ORDERS:<CODIGO>'. Cualquier
// otro error (conexión, constraint inesperada) sale como UNKNOWN con el mensaje crudo.
// Este nodo y "Error" van ARRIBA de todo en el lienzo: en las lecturas (con
// alwaysOutputData) un error corre las dos salidas y responde el nodo más alto.
const pieces = [
  $json.message,
  $json.error?.message,
  $json.error?.description,
  typeof $json.error === 'string' ? $json.error : null,
].filter((p) => typeof p === 'string' && p.trim());
// Último recurso: el item entero, por si n8n cambia dónde deja el texto.
const haystack = pieces.join('\n') + '\n' + JSON.stringify($json);
const text = pieces[0] ?? 'Error';
const match = haystack.match(/LAB_ORDERS:([A-Z_]+)/);
return [{ json: {
  success: false,
  code: match ? match[1] : 'UNKNOWN',
  message: text,
} }];

// Un item por archivo (binary.data), como /sesiones/upsert antes de "Attachements CRUD".
// Tipos y tamaño iguales a los del frontend (lab-order-attachments.ts).
if (!$json.ok) throw new Error('LAB_ORDERS:NOT_FOUND');
const req = $('POST /lab-orders/attachments/upload').first();
const orderId = String(req.json.body?.order_id ?? '');
const MAX_FILES = 10;
const MAX_BYTES = 10 * 1024 * 1024;
const EXT_3D = /\.(stl|ply|obj)$/i;
// n8n guarda fileSize como texto ("850 kB", "1.2 MB"); con el binario en disco no hay base64 que medir.
const UNITS = { b: 1, kb: 1024, mb: 1024 ** 2, gb: 1024 ** 3 };
function bytesOf(file) {
  const m = String(file.fileSize ?? '').trim().match(/^([\d.]+)\s*([kmg]?b)?$/i);
  if (m) return Number(m[1]) * (UNITS[(m[2] || 'b').toLowerCase()] ?? 1);
  return typeof file.data === 'string' && file.data.length > 64 ? Math.floor(file.data.length * 3 / 4) : 0;
}
const files = Object.values(req.binary ?? {}).filter(Boolean);
if (files.length === 0) throw new Error('LAB_ORDERS:NO_FILES');
if (files.length > MAX_FILES) throw new Error('LAB_ORDERS:TOO_MANY_FILES');
const out = [];
for (const file of files) {
  const name = file.fileName || 'archivo';
  const mime = file.mimeType || '';
  // Imágenes y PDF por tipo; escaneos 3D por extensión (el navegador suele mandarlos como octet-stream).
  const okType = /^image\//i.test(mime) || /^application\/pdf$/i.test(mime) || EXT_3D.test(name);
  if (!okType) throw new Error('LAB_ORDERS:INVALID_FILE_TYPE');
  if (bytesOf(file) > MAX_BYTES) throw new Error('LAB_ORDERS:FILE_TOO_LARGE');
  out.push({ json: { order_id: orderId, fileName: name, mimeType: mime }, binary: { data: file } });
}
return out;

// "Attachements CRUD" no falla: devuelve { success: false } por archivo.
const failed = $input.all().filter((i) => i.json.success === false);
if (failed.length) throw new Error('LAB_ORDERS:UPLOAD_FAILED ' + JSON.stringify(failed[0].json.data ?? {}).slice(0, 300));
return [{ json: { order_id: $('POST /lab-orders/attachments/upload').first().json.body?.order_id } }];

if (!$json.ok) throw new Error('LAB_ORDERS:NOT_FOUND');
const body = $('POST /lab-orders/attachments/delete').first().json.body ?? {};
return [{ json: { order_id: String(body.order_id), attachment_id: String(body.attachment_id) } }];

const failed = $input.all().filter((i) => i.json.success === false);
if (failed.length) throw new Error('LAB_ORDERS:DELETE_FAILED ' + JSON.stringify(failed[0].json.data ?? {}).slice(0, 300));
return [{ json: { order_id: $('Guard delete').first().json.order_id } }];
